const payload = msg.payload || {};
let chatId = payload.chatId;
const messageType = payload.type;
let text = (payload.content || '').trim();
const originalMsg = msg.originalMessage || {};
let userId = originalMsg.from ? originalMsg.from.id : null;
const messageId = originalMsg.message_id;
let answerCallback = null;
if (messageType === 'callback_query') {
    text = payload.data || payload.callback_data || payload.content ||
           (originalMsg.data ? originalMsg.data : '') || '';
    if (!chatId) {
        if (originalMsg.message && originalMsg.message.chat) chatId = originalMsg.message.chat.id;
        else if (originalMsg.chat) chatId = originalMsg.chat.id;
    }
    if (originalMsg.from) userId = originalMsg.from.id;
    const callbackQueryId = payload.callback_query_id || payload.id ||
        (originalMsg.id ? originalMsg.id.toString() : null);
    if (callbackQueryId) {
        answerCallback = {
            payload: { callback_query_id: callbackQueryId, text: '', show_alert: false },
            topic: 'answerCallbackQuery'
        };
    }
}
if ((messageType !== 'message' && messageType !== 'callback_query') || !text || !chatId) {
    return [null, answerCallback].filter(m => m !== null);
}
const command = text.split(' ')[0].toLowerCase();
const args = text.split(' ').slice(1);
if (!command.startsWith('/huawei_')) {
    return [null, answerCallback].filter(m => m !== null);
}
msg.telegram = { chatId, userId, messageId, command, args, originalText: text };
if (command === '/huawei_status') msg.topic = 'huawei_status';
else if (command === '/huawei_help') msg.topic = 'huawei_help';
else msg.topic = 'huawei_unknown';
return [msg, answerCallback].filter(m => m !== null);

if (msg.payload && msg.payload.callback_query_id) {
    msg.payload = {
        callback_query_id: msg.payload.callback_query_id,
        text: msg.payload.text || '',
        show_alert: msg.payload.show_alert || false
    };
    msg.topic = 'answerCallbackQuery';
    return msg;
}
return null;

const fmtW = (v) => {
    if (v == null || v === '') return 'N/A';
    const n = Number(v);
    return Number.isNaN(n) ? String(v) : `${Math.round(n)} W`;
};
const energy = global.get('huawei_energy_state') || {};
const dev = energy.device || {};
const pv = energy.pv || {};
const inv = energy.inverter || {};
if (!energy.timestamp) {
    msg.payload = {
        chatId: msg.telegram.chatId,
        type: 'message',
        content: '⚠️ No Huawei data yet.\n\nCheck `huawei-mqtt-publisher.service` and `energy/huawei/status`.',
        parse_mode: 'Markdown'
    };
    msg.topic = 'send';
    return msg;
}
let t = '☀️ *Huawei SUN2000 Status*\n\n';
t += `📟 *Model:* ${dev.model || '?'}\n`;
t += `🔢 *Serial:* ${dev.serial || '?'}\n\n`;
t += `⚡ *Active power:* ${fmtW(inv.active_power_w)}\n`;
t += `🔆 *DC input:* ${fmtW(pv.input_power_w)}\n`;
t += `📈 *Daily yield:* ${inv.daily_yield_kwh != null ? inv.daily_yield_kwh + ' kWh' : '?'}\n`;
t += `🔌 *Grid:* ${inv.grid_frequency_hz != null ? inv.grid_frequency_hz + ' Hz' : '?'}\n\n`;
t += `*PV1:* ${pv.string1_voltage_v ?? '?'} V / ${pv.string1_current_a ?? '?'} A\n`;
t += `*PV2:* ${pv.string2_voltage_v ?? '?'} V / ${pv.string2_current_a ?? '?'} A\n`;
if (energy.lastReportedMs) {
    const age = Math.max(0, Math.floor((Date.now() - energy.lastReportedMs) / 1000));
    t += `\n🕐 Updated ${Math.floor(age / 60)}:${String(age % 60).padStart(2, '0')} ago`;
}
msg.payload = { chatId: msg.telegram.chatId, type: 'message', content: t, parse_mode: 'Markdown' };
msg.topic = 'send';
return msg;

const helpText = `☀️ *Huawei SUN2000 Bot*\n\n` +
    `📊 \`/huawei_status\` — PV power, yield, strings\n` +
    `❓ \`/huawei_help\` — this help\n\n` +
    `*MQTT:* energy/huawei/status\n` +
    `*Service:* huawei-mqtt-publisher.service`;
const inlineKeyboard = {
    inline_keyboard: [[
        { text: '📊 Status', callback_data: '/huawei_status' },
        { text: '❓ Help', callback_data: '/huawei_help' }
    ]]
};
msg.payload = {
    chatId: msg.telegram.chatId,
    type: 'message',
    content: helpText,
    parse_mode: 'Markdown',
    options: { reply_markup: JSON.stringify(inlineKeyboard) }
};
msg.topic = 'send';
return msg;

msg.payload = {
    chatId: msg.telegram.chatId,
    type: 'message',
    content: `❓ Unknown Huawei command: ${msg.telegram.originalText}\n\nType /huawei_help for available commands.`
};
msg.topic = 'send';
return msg;
